Definition sa_W2 (sp P SZ T : Z) : list (Z * Z) :=
  [(shad P, shad P + 512); (shad (P + 4096 + SZ), shad (P + sa_msz SZ)); (T + 2872, T + 2888); (P, P + 24);
   (i_sec_mutex, i_sec_mutex + 4); (sp - 64, sp)]%Z.

